 if(p.setFloatArrayElement(0,"flexWeights",-1,0x40000000,phase)||p.setFloatArrayElement(0,"flexWeights",3,0x40000000,phase)||p.setFloatArrayElement(0,"missing",0,0x40000000,phase)||p.setFloatArrayElement(0,"flexWeights",2,0,phase))throw std::runtime_error("bounds/equal writes accepted");
